const KEY = env.get("stateName") || "messageGate";
const LABEL = env.get("label") || KEY;
const DEFAULT = env.get("default") === true || env.get("default") === "true";

function statusMsg(enabled) {
    return {
        payload: {
            fill: enabled ? "green" : "red",
            shape: "dot",
            text: enabled ? "ENABLED" : "BLOCKED"
        }
    };
}

function stateMsg(enabled) {
    return {
        payload: enabled,
        topic: KEY,
        gate: {
            name: KEY,
            label: LABEL,
            enabled: enabled
        }
    };
}

let enabled = flow.get(KEY, "file");

if (typeof enabled !== "boolean") {
    enabled = DEFAULT;
    flow.set(KEY, enabled, "file");
}

// ----- Control message -----
let control;

if (typeof msg.enable === "boolean") {
    control = msg.enable;
}
else if (msg.topic === "enable" && typeof msg.payload === "boolean") {
    control = msg.payload;
}

if (typeof control === "boolean") {
    const previous = enabled;
    enabled = control;

    if (previous !== enabled) {
        flow.set(KEY, enabled, "file");
        return [null, stateMsg(enabled), statusMsg(enabled)];
    }

    return [null, null, statusMsg(enabled)];
}

// ----- Normal message -----
if (enabled) {
    return [msg, null, statusMsg(enabled)];
}

return [null, null, statusMsg(enabled)];

