const notification = flow.get("notification") || {};
const wa = notification.whatsapp || {};


const emoji = {
    info: "ℹ️",
    warning: "⚠️",
    critical: "🚨"
};

const alert = msg.alert || {
    title: "No title",
    message: msg.payload,
    severity: "info"
};

// Default routing
const notify = Object.assign(
    { ha: true, whatsapp: true },
    alert.notify || {}
);

const source = alert.source ? `[${alert.source}] ` : "";
const message =
    `${emoji[alert.severity] || ""} ${source}${alert.message}`;

// WhatsApp payload
let sendWA = false;
if (notify.whatsapp && (wa.group || wa.number)) {

    msg.whatsapp = {
        message: message
    };

    if (wa.group) {
        msg.whatsapp.group = wa.group;
    } else {
        msg.whatsapp.number = wa.number;
    }

    // safety fallback (important)
    if (!msg.whatsapp.group && !msg.whatsapp.number) {
        node.warn("WhatsApp target missing (group or number)");
        return msg;
    }
    sendWA = true;
}
// attach flag
msg._sendWA = sendWA;


// Home Assistant payload
let sendHA = false;
if (notify.ha) {
    msg.ha = {
        title: alert.title,
        message: message
    };
    sendHA = true;
}
// attach flag
msg._sendHA = sendHA;

return msg;

// Successful HomeWizard response
// Reset communication error counter
flow.set('hwErrors', 0);

const power = Number(msg.payload.active_power_w);

if (power > 50) {
    msg.payload = 'RUNNING';
} else {
    msg.payload = 'STOPPED';
}

msg.power = power;

return msg;

/*
If the safety switch on the Somfy motor has cut off the power, an EHOSTUNREACH error message is received via the HW API (
status RequestError: connect EHOSTUNREACH 192.168.1.34:80)
In that case, the message “Locked” is displayed on the dashboard
*/

let errors = flow.get('hwErrors') || 0;
errors++;
flow.set('hwErrors', errors);

if (errors >= 2) {
    msg.payload = 'LOCKED';
    return msg;
}

return null;

// Enable rain alert gate only when awning is NOT at 0%

const position = Number(msg.payload);

// Ignore invalid values
if (isNaN(position)) {
    node.warn("Invalid awning position: " + msg.payload);
    return null;
}

// 0% = awning closed/retracted → disable rain notifications
// anything else = awning open → enable rain notifications
const enableGate = position !== 0;

msg.topic = "enable";
msg.payload = enableGate;

msg.awning = {
    position: position,
    rainAlertGate: enableGate ? "enabled" : "disabled"
};

node.status({
    fill: enableGate ? "green" : "red",
    shape: "dot",
    text: enableGate
        ? `ENABLED - awning ${position}%`
        : "BLOCKED - awning 0%"
});
return msg;

