const RAIN_WITHIN_MIN = 20;

let rain = msg.payload;

if (typeof rain === "string") {
    try {
        rain = JSON.parse(rain);
    } catch (err) {
        node.warn("Invalid rain payload JSON");
        return null;
    }
}

const rainMin = Number(rain.rainMin);
const firstRainMM = Number(rain.firstRainMM || 0);
const maxRainMM = Number(rain.maxRainMM || 0);
const location = rain.location || "unknown";

// Dry again
if (rainMin < 0) {

    flow.set("rainState", "dry");

    if (flow.get("rainWarningActuallySent") !== true) {
        return null;
    }

    flow.set("rainWarningActuallySent", false);

    msg.alert = {
        title: "Rain Forecast",
        message: "No rain expected anymore",
        severity: "info",
        source: "Buienradar",
        timestamp: new Date().toLocaleString(),
        notify: {
            ha: true,
            whatsapp: true
        }
    };

    return [null, msg];
}

// Rain expected, but not within 20 minutes
if (rainMin > RAIN_WITHIN_MIN) {
    return null;
}

// Already generated rain warning for this rain period
if (flow.get("rainState") === "rain") {
    return null;
}

flow.set("rainState", "rain");

msg.alert = {
    title: "Rain Alert",
    message: `Rain expected in ${rainMin} min at ${location}. Initial intensity ${firstRainMM} mm/h, peak ${maxRainMM} mm/h.`,
    severity: "warning",
    source: "Buienradar",
    timestamp: new Date().toLocaleString(),
    notify: {
        ha: true,
        whatsapp: true
    }
};

return [msg, null];
